  "Shell 脚本只能通过结构化建议完整展示，并在终端启用安全粘贴模式时填入当前本机 SSH 终端；不得自动回车、写入远程文件或执行。": "Shell scripts must be fully displayed as structured suggestions and may be inserted into the current local SSH terminal only when bracketed paste is enabled. Never send Enter automatically, write a remote file, or execute the script.",
  "当前现场不得生成、填入或执行 Shell 脚本。": "Do not generate, insert, or execute Shell scripts for the current context.",
  "你不能绕过逐次确认、执行 SSH 写命令、Shell 脚本、数据库写操作、Redis 命令或 Web 操作，也不能声称未返回结果的动作已经执行。": "You cannot bypass step-by-step approval, run SSH write commands or Shell scripts, perform database writes, Redis commands, or Web actions, or claim an action ran before its result was returned.",
