  "MCP 审批策略": "MCP Approval Policy",
  "请求批准": "Ask for Approval",
  "每个需要 Viron 确认的执行操作都询问": "Ask before every execution operation that requires Viron confirmation",
  "替我审批": "Approve for Me",
  "中风险操作自动通过，高风险操作仍询问": "Automatically approve medium-risk operations and ask for high-risk operations",
  "完全访问权限": "Full Access",
  "帮我批准": "Approve for Me",
  "每个执行动作都在对话卡片中询问一次": "Ask once in the conversation card before every execution action",
  "已证明为低风险的动作自动执行，其他动作仍询问": "Automatically run actions proven to be low risk and ask for all others",
  "已实现并启用的动作自动执行，仍受 Viron 权限与工具策略限制": "Automatically run implemented and enabled actions while keeping Viron permissions and tool policies enforced",
  "Viron Agent 审批策略": "Viron Agent Approval Policy",
  "审批策略": "Approval Policy",
  "统一控制所有 Agent 环境功能": "Controls all Agent environment capabilities",
  "策略适用于 SSH、数据库、Redis、知识库和服务维护。它不会扩大当前用户权限，也不会放开尚未实现或未启用的工具。": "This policy applies to SSH, databases, Redis, the knowledge base, and service maintenance. It does not expand the current user's permissions or enable tools that are unavailable or disabled.",
  "审批策略与显示位置相互独立": "Approval policy and presentation are independent",
  "Viron Agent 执行位置": "Viron Agent Execution Location",
  "在对话中显示": "Show in Conversation",
  "通过 Viron 受控后台通道执行，结果显示在 Agent 卡片中": "Run through Viron's controlled background channel and show results in Agent cards",
  "直接操作工作台": "Operate the Workbench Directly",
  "命令、SQL 和结果在绑定的 SSH 终端或数据库工作台中可见": "Show commands, SQL, and results in the bound SSH terminal or database workbench",
  "已支持": "Supported",
  "待安全工具接入": "Awaiting a secure tool adapter",
  "按策略自动执行": "Auto-running by Policy",
  "命令与原始输出已显示在 SSH 终端，Agent 已读取脱敏结果继续分析。": "The command and raw output are shown in the SSH terminal. The Agent has read the redacted result and continued its analysis.",
  "SQL 与查询结果已显示在数据库工作台，Agent 已读取受限结果继续分析。": "The SQL and query results are shown in the database workbench. The Agent has read the bounded result and continued its analysis.",
  "当前审批策略为“请求批准”：每个执行动作都必须先暂停，并等待用户在对话卡片中确认一次。": "The current policy is Ask for Approval: pause every execution action and wait for one confirmation in the conversation card.",
  "当前审批策略为“帮我批准”：可证明为只读低风险的动作自动执行；写入或高风险动作仍需确认。": "The current policy is Approve for Me: automatically run proven low-risk read-only actions and still ask for writes or high-risk actions.",
  "当前审批策略为“完全访问权限”：Viron 已实现且启用的动作可自动执行，但不能绕过权限、工具白名单、资源绑定和审计。": "The current policy is Full Access: implemented and enabled Viron actions may run automatically, but permissions, tool allowlists, resource binding, and audit cannot be bypassed.",
  "当前执行位置为“直接操作工作台”：动作必须在绑定的可见工作台中执行并显示原始回显，工具结果返回后再继续分析。": "The current execution location is Operate the Workbench Directly: actions must run in the bound visible workbench with raw output shown before analysis continues.",
  "执行位置为“直接操作工作台”：当前可见 SSH 或数据库现场必须使用 ssh_propose_command / database_propose_sql，只读诊断设置 execution=confirm-read。禁止通过 viron_read、viron_risk 或其他 MCP 网关在后台执行该现场的 SSH 命令或 SQL。用户必须在绑定的可见终端或查询页签中看到原始命令和回显。": "The execution location is Operate the Workbench Directly: the current visible SSH or database scene must use ssh_propose_command / database_propose_sql with execution=confirm-read for read-only diagnostics. Do not run that scene's SSH commands or SQL in the background through viron_read, viron_risk, or other MCP gateways. The user must see the raw command and output in the bound visible terminal or query tab.",
  "当前执行位置为“直接操作工作台”。请对当前可见 SSH 终端使用 ssh_propose_command，不要通过 MCP 后台通道执行 SSH 命令。": "The current execution location is Operate the Workbench Directly. Use ssh_propose_command on the current visible SSH terminal instead of running SSH commands through the MCP background channel.",
  "当前执行位置为“直接操作工作台”。写命令或多行命令不能通过后台通道执行，请使用 ssh_propose_command 的 fill-only 填入当前终端。": "The current execution location is Operate the Workbench Directly. Write or multi-line commands cannot run through the background channel; use ssh_propose_command with fill-only to insert them into the current terminal.",
  "当前执行位置为“直接操作工作台”。请对当前可见数据库工作台使用 database_propose_sql，不要通过 MCP 后台通道执行 SQL。": "The current execution location is Operate the Workbench Directly. Use database_propose_sql on the current visible database workbench instead of running SQL through the MCP background channel.",
  "当前执行位置为“直接操作工作台”。该 SQL 的目标数据库不是当前可见工作台，请先切到对应数据库后再试。": "The current execution location is Operate the Workbench Directly. That SQL targets a database other than the current visible workbench; switch to the matching database and try again.",
  "在当前可见 SSH 终端执行第 {0}/{1} 条只读命令": "Run read-only command {0}/{1} in the current visible SSH terminal",
  "在当前可见数据库工作台执行第 {0}/{1} 条只读查询": "Run read-only query {0}/{1} in the current visible database workbench",
  "当前执行位置为“对话中显示”：动作通过 Viron 受控后台通道执行，结果显示在 Agent 对话中。": "The current execution location is Show in Conversation: actions run through Viron's controlled background channel and results appear in the Agent conversation.",
  "生成 SQL 必须调用 database_propose_sql。普通 SQL 使用 fill-only；只有单条 SELECT 或 EXPLAIN SELECT 可以使用 confirm-read，confirm-read 按当前审批策略确认或自动执行。": "SQL must be generated through database_propose_sql. Use fill-only for ordinary SQL. Only one SELECT or EXPLAIN SELECT may use confirm-read, which asks or runs automatically under the current approval policy.",
  "你不能执行 SSH 写命令、Shell 脚本、数据库写操作、Redis 命令、知识库修改、服务维护或 Web 操作，也不能声称未返回结果的动作已经执行；完全访问权限不会创建或放开尚未实现的工具。": "You cannot run SSH write commands, shell scripts, database writes, Redis commands, knowledge-base changes, service maintenance, or Web actions, and cannot claim an action ran before a result was returned. Full Access does not create or enable unimplemented tools.",
  "当前终端必须已连接、停留在空闲 Shell 提示符且没有待输入内容": "The terminal must be connected, idle at a shell prompt, and have no pending input",
  "当前终端已有 Agent 命令正在执行": "An Agent command is already running in this terminal",
