  "按当前 Viron Agent 审批策略执行 {{0}} SSH 只读诊断命令{{1}}": "Run the {{0}} read-only SSH diagnostic command under the current Viron Agent approval policy{{1}}",
  "按当前 Viron Agent 审批策略执行数据库只读查询{{0}}": "Run the read-only database query under the current Viron Agent approval policy{{0}}",
  "在当前 SSH 终端执行只读诊断命令（第 {{0}}/{{1}} 步）": "Run the read-only diagnostic in the current SSH terminal (step {{0}}/{{1}})",
  "SSH 终端只读诊断完成，耗时 {{0}} ms，输出脱敏 {{1}} 处{{2}}": "Read-only SSH terminal diagnostic completed in {{0}} ms with {{1}} redaction(s){{2}}",
  "在当前数据库工作台执行只读查询（第 {{0}}/{{1}} 步）": "Run the read-only query in the current database workbench (step {{0}}/{{1}})",
  "数据库工作台只读查询完成，返回 {{0}} 行": "Read-only database workbench query completed with {{0}} row(s)",
  "风险操作直接执行，不再显示审批弹窗": "Execute risk operations directly without Viron approval windows",
  "本机 MCP 审批策略": "Local MCP Approval Policy",
  "只控制 Viron 是否要求二次确认；不会扩大当前用户、工作空间或连接权限。": "Controls only Viron secondary confirmation and does not expand user, workspace, or connection permissions.",
  "Codex 客户端还有独立审批层。要与当前策略一致，请在该 MCP Server 配置中设置：": "Codex has a separate client approval layer. To align it with this policy, set the following on this MCP server:",
  "远程 MCP 的 Viron 审批策略按个人 API Key 保存，可在“API Key”中为每个 Codex 连接独立设置。": "Viron remote MCP approval policy is stored per personal API key and can be configured independently for each Codex connection under API Key.",
  "管理 API Key": "Manage API Keys",
  "完全访问会让 Agent 在当前 Viron 用户权限内直接执行 SSH、数据库、Redis、SFTP 和 Web 风险操作。凭据输入、账号权限和秘密导出限制仍然保留。": "Full Access lets the agent directly execute SSH, database, Redis, SFTP, and Web risk operations within the current Viron user's permissions. Credential input, account permissions, and secret export restrictions remain enforced.",
  "开启 MCP 完全访问": "Enable MCP Full Access",
